queries.query:
query ZubatEvolutionTypes($where: pokemonspecies_bool_exp!, $speciesLimit: Int!, $pokemonLimit: Int!, $typeLimit: Int!) {
  pokemonspecies(where: $where, limit: 1) {
    id
    name
    evolutionchain {
      pokemonspecies(order_by: {id: asc}, limit: $speciesLimit) {
        id
        name
        pokemons(where: {is_default: {_eq: true}}, limit: $pokemonLimit) {
          id
          name
          pokemontypes(limit: $typeLimit, order_by: {slot: asc}) {
            type { name }
          }
        }
      }
    }
  }
}

query GetZubatEvolutionAndTypes($name: String!, $limitSpecies: Int!, $limitChainSpecies: Int!, $limitPokemons: Int!, $limitTypes: Int!) {
  pokemonspecies(where: {name: {_eq: $name}}, limit: $limitSpecies) {
    id
    name
    evolutionchain {
      id
      pokemonspecies(order_by: {id: asc}, limit: $limitChainSpecies) {
        id
        name
        pokemons(where: {is_default: {_eq: true}}, limit: $limitPokemons) {
          id
          name
          pokemontypes(limit: $limitTypes) {
            type {
              id
              name
            }
          }
        }
      }
    }
  }
}

query KantoFinalEvolutions($names: [String!]!, $limit: Int!, $typeLimit: Int!) {
