query Original151Intimidate($maxId: Int!, $abilityName: String!, $isDefault: Boolean!, $limit: Int!) {
  pokemonspecies(
    where: {
      id: {_lte: $maxId}
      pokemons: {
        is_default: {_eq: $isDefault}
        pokemonabilities: {ability: {name: {_eq: $abilityName}}}
      }
    }
    order_by: {id: asc}
    limit: $limit
  ) {
    id
    name
    pokemons(limit: 1, where: {is_default: {_eq: $isDefault}}) {
      id
      name
      pokemonabilities(limit: 10) {
        ability { id name }
        is_hidden
      }
    }
  }
}

query GetGen1PokemonWithIntimidate($abilityName: String!, $maxSpeciesId: Int!, $limit: Int!) {
  pokemonspecies(
    where: {
      id: {_lte: $maxSpeciesId}
      pokemons: {
        pokemonabilities: {
          ability: {name: {_eq: $abilityName}}
        }
      }
    }
    order_by: {id: asc}
    limit: $limit
  ) {
    id
    name
    pokemons(where: {is_default: {_eq: true}}, limit: 1) {
      id
      name
      pokemonabilities(where: {ability: {name: {_eq: $abilityName}}}, limit: 5) {
        is_hidden
        slot
        ability {
          id
          name
        }
      }
    }
  }
}

query ShedinjaAbilityEffect($pokemonName: String!, $languageCode: String!, $pokemonLimit: Int!, $abilityLimit: Int!, $effectLimit: Int!) {
  pokemon(where: {name: {_eq: $pokemonName}}, limit: $pokemonLimit) {
    id
    name
    pokemonabilities(limit: $abilityLimit, order_by: {slot: asc}) {
      ability {
        id
        name
        abilityeffecttexts(where: {language: {iso639: {_eq: $languageCode}}}, limit: $effectLimit) {
          id
          short_effect
          effect
          language { id name }
        }
      }
      is_hidden
      slot
    }
  }
}

query GetShedinjaAbility($name: String!, $lang: String!, $limit: Int!) {
  pokemon(where: {name: {_eq: $name}}, limit: $limit) {
    id
    name
    pokemonabilities(limit: $limit) {
      is_hidden
      ability {
        id
        name
        abilityflavortexts(where: {language: {iso639: {_eq: $lang}}}, order_by: {version_group_id: desc}, limit: 1) {
          flavor_text
        }
        abilityeffecttexts(where: {language: {iso639: {_eq: $lang}}}, limit: 1) {
          effect
          short_effect
        }
      }
    }
  }
}

query FirstGenLevitate($generationId: Int!, $isDefault: Boolean!, $abilityName: String!, $limit: Int!, $offset: Int!) {
  pokemonspecies(where: {generation_id: {_eq: $generationId}, pokemons: {is_default: {_eq: $isDefault}, pokemonabilities: {ability: {name: {_eq: $abilityName}}}}}, order_by: {id: asc}, limit: $limit, offset: $offset) {
    id
    name
    pokemons(limit: 1, where: {is_default: {_eq: $isDefault}}) {
      id
      name
      pokemonabilities(limit: 6, where: {ability: {name: {_eq: $abilityName}}}) { id ability_id is_hidden slot ability { id name } }
    }
  }
}

